/* =====================================================================
   GOT App — activity logger  (window.__GOT_LOG)
   Appended to the bundle. Depends only on window.__GOT_SB (the supabase
   client the app already built) which a one-line patch exposes.

   Never records what anyone typed. Only which screen was opened, when,
   and for how long.
   ===================================================================== */
(function () {
  if (typeof window === "undefined" || window.__GOT_LOG) return;

  var VER = (window.__GOT_VERSION && window.__GOT_VERSION.v) || "1.0.0";
  var FLUSH_MS = 8000;        // drain the queue this often
  var MAX_BATCH = 40;
  var HEARTBEAT_MS = 60000;   // one row per minute of screen time
  var q = [], timer = null, hb = null, sending = false;
  var ident = { smfid: null, email: null, role: null };
  var started = Date.now(), lastTab = null, told = false;

  function sid() {
    try {
      var k = "got_sid", v = sessionStorage.getItem(k);
      if (!v) {
        v = (window.crypto && crypto.randomUUID)
          ? crypto.randomUUID()
          : Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
        sessionStorage.setItem(k, v);
      }
      return v;
    } catch (e) { return "nosession"; }
  }
  var SID = sid();

  function device() {
    var u = navigator.userAgent || "";
    if (/iPhone|iPad|iPod/i.test(u)) return "ios";
    if (/Android/i.test(u)) return "android";
    return "desktop";
  }
  var DEV = device();
  var SCR = (function () {
    /* Tells us, per client, three things we otherwise have to guess at:
       whether the app launched as an installed PWA or as a browser shortcut,
       the viewport it actually got, and whether env(safe-area-inset-*) is live
       (it is zero unless index.html carries viewport-fit=cover). */
    try {
      var mode = (window.matchMedia && matchMedia("(display-mode: standalone)").matches) ||
                 window.navigator.standalone ? "pwa" : "tab";
      var probe = document.createElement("div");
      probe.style.cssText = "position:fixed;top:-9999px;left:0;width:0;" +
        "padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)";
      document.documentElement.appendChild(probe);
      var cs = getComputedStyle(probe);
      var sa = parseInt(cs.paddingTop, 10) + "/" + parseInt(cs.paddingBottom, 10);
      probe.parentNode.removeChild(probe);
      return screen.width + "x" + screen.height +
             " vp" + window.innerWidth + "x" + window.innerHeight +
             " " + mode + " sa" + sa;
    } catch (e) {
      try { return screen.width + "x" + screen.height; } catch (e2) { return ""; }
    }
  })();

  function sb() { return window.__GOT_SB || null; }

  function push(event, detail) {
    if (!event) return;
    q.push({
      ts: new Date().toISOString(),
      smfid: ident.smfid,
      email: ident.email,
      role: ident.role,
      event: event,
      detail: detail == null ? null : String(detail).slice(0, 120),
      session_id: SID,
      device: DEV,
      screen: SCR,
      app_ver: VER
    });
    if (q.length >= MAX_BATCH) flush();
    else if (!timer) timer = setTimeout(flush, FLUSH_MS);
  }

  function flush() {
    if (timer) { clearTimeout(timer); timer = null; }
    if (sending || !q.length) return;
    var c = sb();
    if (!c) { timer = setTimeout(flush, FLUSH_MS); return; }   // client not up yet
    var batch = q.splice(0, MAX_BATCH);
    for (var i = 0; i < batch.length; i++) {
      // rows queued before getSession() came back still deserve an email on them
      if (!batch[i].email) batch[i].email = ident.email;
    }
    sending = true;
    try {
      c.from("app_events").insert(batch).then(function (r) {
        sending = false;
        // a failed write is never allowed to break the app or retry forever
        if (r && r.error && !told) { told = true; try { console.debug("log", r.error.message); } catch (e) {} }
        if (q.length && !timer) timer = setTimeout(flush, FLUSH_MS);
      }, function () { sending = false; });
    } catch (e) { sending = false; }
  }

  /* ---- identity ------------------------------------------------------ */
  function whoami() {
    var c = sb();
    if (!c || !c.auth) return;
    try {
      c.auth.getSession().then(function (r) {
        var s = r && r.data && r.data.session;
        if (s && s.user) ident.email = (s.user.email || "").toLowerCase();
      }, function () {});
    } catch (e) {}
  }

  /* ---- what we watch ------------------------------------------------- */
  function currentTab() {
    try {
      var el = document.querySelector(".tabbar .tab.tab-on span");
      return el ? (el.textContent || "").trim().toLowerCase() : null;
    } catch (e) { return null; }
  }

  function onClick(e) {
    var t = e.target;
    if (!t || !t.closest) return;
    try {
      if (t.closest(".tabbar .tab")) {
        setTimeout(function () {
          var tb = currentTab();
          if (tb && tb !== lastTab) { lastTab = tb; push("tab", tb); }
        }, 40);
        return;
      }
      if (t.closest(".ring-tap")) {
        setTimeout(function () {
          var r = document.querySelector(".ring-tap");
          push("ring", r && r.classList.contains("open") ? "open" : "close");
        }, 40);
        return;
      }
      if (t.closest(".avatar-btn")) { push("profile", null); return; }
      if (t.closest(".w4row"))      { push("week", (t.closest(".w4row").textContent || "").trim().slice(0, 40)); return; }
      var d = t.closest("[data-log]");
      if (d) push(d.getAttribute("data-log"), d.getAttribute("data-log-detail"));
    } catch (err) {}
  }

  function beat() {
    if (document.visibilityState !== "visible") return;
    if (!ident.smfid && !ident.role) return;
    push("heartbeat", currentTab() || lastTab);
  }

  function onHide() {
    if (document.visibilityState === "hidden") {
      push("leave", Math.round((Date.now() - started) / 1000));
      flush();
    }
  }

  /* ---- public API ---------------------------------------------------- */
  window.__GOT_LOG = {
    /* called by the app when a client dashboard finishes loading */
    open: function (smfid, fromAdmin) {
      ident.smfid = smfid || null;
      ident.role = fromAdmin ? "coach" : "client";
      if (!ident.email) whoami();
      if (!this._booted) { this._booted = true; push("login", ident.role); }
      lastTab = null;
      push("open_dashboard", smfid);
      try { window.__GOT_PWA && window.__GOT_PWA.maybeShow(ident.role); } catch (e) {}
      setTimeout(function () {
        var tb = currentTab();
        if (tb && tb !== lastTab) { lastTab = tb; push("tab", tb); }
      }, 400);
    },
    /* the admin list itself */
    admin: function () {
      ident.role = "coach";
      ident.smfid = null;
      if (!ident.email) whoami();
      if (!this._booted) { this._booted = true; push("login", "coach"); }
      push("open_admin", null);
    },
    signout: function () { push("signout", null); flush(); },
    event: push,
    flush: flush
  };

  document.addEventListener("click", onClick, true);
  document.addEventListener("visibilitychange", onHide);
  window.addEventListener("pagehide", onHide);
  hb = setInterval(beat, HEARTBEAT_MS);
  whoami();
})();

/* =====================================================================
   GOT App — add-to-home-screen prompt  (window.__GOT_PWA)

   Appended to the bundle. Plain DOM, nothing touches the React tree.

   Shown once, to a signed-in client, on a phone, when the app is not
   already installed. Never on the sign-in screen, never to the coach,
   never inside the installed app, never on desktop.
   ===================================================================== */
(function () {
  if (typeof window === "undefined" || window.__GOT_PWA) return;

  var KEY = "got_pwa_dismissed";
  var AGAIN_AFTER_DAYS = 60;      // one more nudge if still not installed
  var DELAY_MS = 3500;            // let the dashboard settle first
  var deferred = null, shown = false, node = null, toldStandalone = false;

  function ua() { return navigator.userAgent || ""; }
  function isStandalone() {
    try {
      return (window.matchMedia && window.matchMedia("(display-mode: standalone)").matches) ||
             navigator.standalone === true;
    } catch (e) { return false; }
  }
  function isIOS() {
    return /iPad|iPhone|iPod/.test(ua()) ||
           // iPadOS 13+ reports as a Mac, but a Mac has no touch screen
           (/Macintosh/.test(ua()) && navigator.maxTouchPoints > 1);
  }
  function isAndroid() { return /Android/.test(ua()); }
  /* Instagram / Facebook / LinkedIn open links in their own web view, which has
     no "add to home screen" at all. Telling someone to look for a button that
     is not there is worse than saying nothing. */
  function inAppBrowser() {
    return /FBAN|FBAV|FB_IAB|Instagram|LinkedInApp|Line\/|Twitter|Snapchat|MicroMessenger/i.test(ua());
  }
  function dismissedRecently() {
    try {
      var v = localStorage.getItem(KEY);
      if (!v) return false;
      var t = Number(v);
      if (!t) return true;                       // old boolean flag: treat as dismissed
      return (Date.now() - t) < AGAIN_AFTER_DAYS * 864e5;
    } catch (e) { return false; }
  }
  function remember() { try { localStorage.setItem(KEY, String(Date.now())); } catch (e) {} }
  function log(ev, detail) { try { window.__GOT_LOG && window.__GOT_LOG.event(ev, detail); } catch (e) {} }

  window.addEventListener("beforeinstallprompt", function (e) {
    e.preventDefault();          // we choose the moment, not Chrome
    deferred = e;
  });
  window.addEventListener("appinstalled", function () { log("installed", null); close(); });

  function close() {
    if (node && node.parentNode) node.parentNode.removeChild(node);
    node = null;
  }

  function el(tag, style, text) {
    var n = document.createElement(tag);
    if (style) n.setAttribute("style", style);
    if (text != null) n.textContent = text;
    return n;
  }

  function card(title, body, actionLabel, onAction) {
    var wrap = el("div",
      "position:fixed;left:12px;right:12px;bottom:calc(84px + env(safe-area-inset-bottom,0px));" +
      "z-index:80;max-width:406px;margin:0 auto;box-sizing:border-box;" +
      "background:#1C1714;border:1px solid #40342B;border-radius:16px;" +
      "box-shadow:0 18px 40px rgba(0,0,0,.6);padding:15px 15px 13px;" +
      "font-family:inherit;color:#F6F1EA;opacity:0;transform:translateY(10px);" +
      "transition:opacity .28s ease,transform .28s ease");

    var head = el("div", "display:flex;align-items:flex-start;gap:11px");
    var icon = el("div",
      "flex:0 0 auto;width:38px;height:38px;border-radius:11px;background:#241D18;" +
      "border:1px solid #40342B;display:flex;align-items:center;justify-content:center;" +
      "font-size:19px;font-weight:800;color:#E8763A;line-height:1", "में");
    var txt = el("div", "flex:1 1 auto;min-width:0");
    txt.appendChild(el("div", "font-size:14px;font-weight:700;margin-bottom:3px", title));
    txt.appendChild(el("div", "font-size:12px;line-height:1.5;color:#A5978A", body));
    var x = el("button",
      "flex:0 0 auto;background:none;border:none;color:#6E5F52;font-size:19px;line-height:1;" +
      "cursor:pointer;padding:0 2px;margin:-2px -2px 0 0", "×");
    x.setAttribute("aria-label", "Dismiss");
    x.onclick = function () { remember(); log("install_dismissed", null); close(); };
    head.appendChild(icon); head.appendChild(txt); head.appendChild(x);
    wrap.appendChild(head);

    if (actionLabel) {
      var b = el("button",
        "width:100%;margin-top:12px;padding:10px 14px;border-radius:11px;border:1px solid #E8763A;" +
        "background:#E8763A;color:#1a0f08;font-weight:700;font-size:14px;cursor:pointer;" +
        "font-family:inherit", actionLabel);
      b.onclick = onAction;
      wrap.appendChild(b);
    }

    document.body.appendChild(wrap);
    node = wrap;
    // one frame later so the transition actually runs
    setTimeout(function () { wrap.style.opacity = "1"; wrap.style.transform = "translateY(0)"; }, 30);
    return wrap;
  }

  function showAndroid() {
    card("Keep GOT on your home screen",
         "Add it once and it opens like an app — full screen, no address bar.",
         "Add to home screen",
         function () {
           log("install_accepted", null);
           var d = deferred; deferred = null; remember(); close();
           if (d && d.prompt) d.prompt();
         });
    log("install_prompt_shown", "android");
  }

  function showIOS() {
    var chrome = /CriOS/.test(ua());
    card("Keep GOT on your home screen",
         chrome
           ? "Tap the ⋯ menu below, then “Add to Home Screen”. It opens full screen after that."
           : "Tap the Share button below, then “Add to Home Screen”. It opens full screen after that.",
         "Got it",
         function () { remember(); log("install_accepted", "ios-instructions"); close(); });
    log("install_prompt_shown", "ios");
  }

  window.__GOT_PWA = {
    /* Called by the logger once a client dashboard has loaded. */
    maybeShow: function (role) {
      if (isStandalone()) {
        if (!toldStandalone) { toldStandalone = true; log("standalone", null); }
        return;
      }
      if (shown || role === "coach") return;
      if (inAppBrowser() || dismissedRecently()) return;
      if (!isIOS() && !isAndroid()) return;             // desktop: leave it alone
      shown = true;
      setTimeout(function () {
        if (isStandalone()) return;
        if (isAndroid()) { if (deferred) showAndroid(); }   // no prompt available, say nothing
        else showIOS();
      }, DELAY_MS);
    },
    close: close,
    /* so you can see it on demand: __GOT_PWA.preview() */
    preview: function () { shown = false; try { localStorage.removeItem(KEY); } catch (e) {} 
      if (isAndroid() && deferred) showAndroid(); else showIOS(); }
  };
})();
